<?php require_once __DIR__ . '/../src/partials.php';$pdo=db();$stats=$pdo->query("SELECT COUNT(*) products,COALESCE(SUM(current_stock),0) stock,COUNT(*) FILTER(WHERE current_stock<=min_stock) low FROM products")->fetch();$month=(int)date('m');$year=(int)date('Y');$out=$pdo->prepare("SELECT COALESCE(SUM(quantity),0) FROM stock_movements WHERE movement_type='OUT' AND EXTRACT(MONTH FROM created_at)=? AND EXTRACT(YEAR FROM created_at)=?");$out->execute([$month,$year]);$outQty=$out->fetchColumn();$rows=$pdo->query("SELECT TO_CHAR(months.month,'YYYY-MM') label,COALESCE(SUM(m.quantity),0) qty FROM generate_series(date_trunc('month',CURRENT_DATE)-interval '11 months',date_trunc('month',CURRENT_DATE),interval '1 month') months(month) LEFT JOIN stock_movements m ON m.movement_type='OUT' AND date_trunc('month',m.created_at)=months.month GROUP BY months.month ORDER BY months.month")->fetchAll();$top=$pdo->query("SELECT p.name,SUM(m.quantity) qty FROM stock_movements m JOIN products p ON p.id=m.product_id WHERE m.movement_type='OUT' AND m.created_at>=date_trunc('month',CURRENT_DATE)-interval '5 months' GROUP BY p.id,p.name ORDER BY qty DESC LIMIT 8")->fetchAll();page_start('แดชบอร์ด');?><div class="grid"><div class="card stat-card"><div class="stat-head"><div><div class="muted">สินค้าทั้งหมด</div></div><div class="stat-icon">▣</div></div><div class="metric"><?=number_format($stats['products'])?></div></div><div class="card stat-card"><div class="stat-head"><div><div class="muted">สินค้าคงเหลือรวม</div></div><div class="stat-icon green">✓</div></div><div class="metric"><?=number_format($stats['stock'])?></div></div><div class="card stat-card"><div class="stat-head"><div><div class="muted">ต่ำกว่าจุดขั้นต่ำ</div></div><div class="stat-icon red">!</div></div><div class="metric low"><?=number_format($stats['low'])?></div></div><div class="card stat-card"><div class="stat-head"><div><div class="muted">เบิกเดือนนี้</div></div><div class="stat-icon orange">↗</div></div><div class="metric"><?=number_format($outQty)?></div></div></div><div class="card chart-card"><div class="chart-head"><h3>แนวโน้มการเบิกสินค้า 12 เดือน</h3><span class="badge success-bg">ย้อนหลัง 12 เดือน</span></div><canvas id="monthlyChart"></canvas></div><div class="card chart-card"><div class="chart-head"><h3>สินค้าที่มีการเบิกสูงสุดใน 6 เดือนล่าสุด</h3><span class="badge success-bg">Top 8</span></div><canvas id="topChart"></canvas></div><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><script>const monthly=<?=json_encode($rows,JSON_UNESCAPED_UNICODE)?>;const top=<?=json_encode($top,JSON_UNESCAPED_UNICODE)?>;new Chart(document.getElementById('monthlyChart'),{type:'line',data:{labels:monthly.map(x=>x.label),datasets:[{label:'จำนวนเบิก',data:monthly.map(x=>Number(x.qty)),tension:.35,fill:true}]},options:{responsive:true,plugins:{legend:{display:false}},scales:{y:{beginAtZero:true}}}});new Chart(document.getElementById('topChart'),{type:'bar',data:{labels:top.map(x=>x.name),datasets:[{label:'จำนวนเบิก',data:top.map(x=>Number(x.qty))}]},options:{responsive:true,indexAxis:'y',plugins:{legend:{display:false}},scales:{x:{beginAtZero:true}}}});</script><?php page_end();
